import{_ as p,a0 as o,w as a,s as u,ao as n,I as r,a1 as l,A as s,x as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const h=JSON.parse('{"title":"使用樹莓派建立一個帶有移動網絡連接功能的路由器 | LCTT x X-CMD","titleTemplate":false,"description":"使用樹莓派建立一個帶有移動網絡連接功能的路由器 | LCTT (202204) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用樹莓派建立一個帶有移動網絡連接功能的路由器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用樹莓派建立一個帶有移動網絡連接功能的路由器 | LCTT (202204) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202204/20210312 Build a router with mobile connectivity using Raspberry Pi","title":"使用樹莓派建立一個帶有移動網絡連接功能的路由器","tag":"202204","desc":""},"relativePath":"202204/20210312 Build a router with mobile connectivity using Raspberry Pi.md","filePath":"[post].md"}'),d={name:"202204/20210312 Build a router with mobile connectivity using Raspberry Pi.md"};function b(f,t,g,m,y,w){const i=o("Link");return a(),u("div",null,[t[49]||(t[49]=n('<h1 id="使用樹莓派建立一個帶有移動網絡連接功能的路由器" tabindex="-1">使用樹莓派建立一個帶有移動網絡連接功能的路由器 <a class="header-anchor" href="#使用樹莓派建立一個帶有移動網絡連接功能的路由器" aria-label="Permalink to “使用樹莓派建立一個帶有移動網絡連接功能的路由器”">​</a></h1><blockquote><p>在你的網絡路由器上使用 OpenWRT 獲得更多控制功能。</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/mesh_networking_dots_connected.png?itok=ovINTRR3" alt="Mesh networking connected dots" title="Mesh networking connected dots"></p><p>樹莓派是一種小型單板電腦，儘管只有信用卡大小，但是能做許多事情。實際上，這個小電腦幾乎可以成為你想讓它成為的任何東西，只要你打開想像力。</p><p>樹莓派愛好者已經做了許多不同的項目，從簡單的程序到複雜的自動化項目和解決方案，如氣象站，甚至智能家居設備。這篇文章將展示怎樣使用 OpenWRT 項目將你的樹莓派變成帶有 LTE 移動網絡連接功能的路由器。</p><h3 id="關於-openwrt-和-lte" tabindex="-1">關於 OpenWRT 和 LTE <a class="header-anchor" href="#關於-openwrt-和-lte" aria-label="Permalink to “關於 OpenWRT 和 LTE”">​</a></h3>',6)),r("p",null,[l(i,{href:"https://openwrt.org/"},{default:s(()=>[...t[0]||(t[0]=[e("OpenWRT",-1)])]),_:1}),t[1]||(t[1]=e(" 是一個利用 Linux 內核為嵌入式設備開發的開源項目，它已經存在超過 15 年了，擁有一個龐大而活躍的社區。",-1))]),t[50]||(t[50]=r("p",null,"有許多使用 OpenWRT 的方法，但是它的主要目的還是用在路由器上。它提供了包管理功能和一個完全可寫的文件系統，並且因為它的的開源屬性，你可以查看和修改代碼，並貢獻到開源生態。如果你想對你的路由器獲得更多的控制，這就是你想要的系統。",-1)),t[51]||(t[51]=r("p",null,[r("ruby",null,[e("長期演進技術"),r("rt",null,"Long-term evolution")]),e("（LTE）是一個基於 GSM/EGDE 和 UMTS/HSPA 技術的無線寬帶通信標準。我使用的 LTE 調製解調器是一個 USB 設備，可以為樹莓派電腦增加 3G 或 4G（LTE）蜂窩連接。")],-1)),t[52]||(t[52]=r("p",null,[r("img",{src:"https://opensource.com/sites/default/files/uploads/lte_modem.png",alt:"Teltonika TRM240 modem",title:"Teltonika TRM240 modem"})],-1)),t[53]||(t[53]=r("h3",{id:"安裝前的準備",tabindex:"-1"},[e("安裝前的準備 "),r("a",{class:"header-anchor",href:"#安裝前的準備","aria-label":"Permalink to “安裝前的準備”"},"​")],-1)),t[54]||(t[54]=r("p",null,"對這個項目來説，你需要：",-1)),r("ul",null,[t[5]||(t[5]=r("li",null,"一個帶有電源線的樹莓派",-1)),t[6]||(t[6]=r("li",null,"一台運行　Linux　的電腦",-1)),t[7]||(t[7]=r("li",null,"一張至少 16GB 的 SD 儲存卡",-1)),t[8]||(t[8]=r("li",null,"以太網線",-1)),r("li",null,[t[3]||(t[3]=e("LTE 調製解調器（我使用的是 Teltonika ",-1)),l(i,{href:"https://teltonika-networks.com/product/trm240/"},{default:s(()=>[...t[2]||(t[2]=[e("TRM240",-1)])]),_:1}),t[4]||(t[4]=e("）",-1))]),t[9]||(t[9]=r("li",null,"一張移動網絡的 SIM 卡",-1))]),t[55]||(t[55]=r("h3",{id:"安裝-openwrt",tabindex:"-1"},[e("安裝 OpenWRT "),r("a",{class:"header-anchor",href:"#安裝-openwrt","aria-label":"Permalink to “安裝 OpenWRT”"},"​")],-1)),r("p",null,[t[11]||(t[11]=e("首先，下載最新的 ",-1)),l(i,{href:"https://downloads.openwrt.org/releases/19.07.7/targets/brcm2708/bcm2710/"},{default:s(()=>[...t[10]||(t[10]=[e("兼容樹莓派的 OpenWRT 的發佈版本",-1)])]),_:1}),t[12]||(t[12]=e("。在 OpenWRT 官網，你可以看到 4 個鏡像：兩個 ",-1)),t[13]||(t[13]=r("strong",null,"ext4",-1)),t[14]||(t[14]=e(" 文件系統的和兩個 ",-1)),t[15]||(t[15]=r("strong",null,"squashfs",-1)),t[16]||(t[16]=e(" 文件系統的。我使用 ",-1)),t[17]||(t[17]=r("strong",null,"ext4",-1)),t[18]||(t[18]=e(" 文件系統。你可以下載 ",-1)),t[19]||(t[19]=r("strong",null,"factory",-1)),t[20]||(t[20]=e(" 或者 ",-1)),t[21]||(t[21]=r("strong",null,"sysupgrade",-1)),t[22]||(t[22]=e(" 鏡像，這兩個都運行良好。",-1))]),t[56]||(t[56]=r("p",null,[r("img",{src:"https://opensource.com/sites/default/files/uploads/imagefiles.png",alt:"OpenWRT image files",title:"OpenWRT image files"})],-1)),r("p",null,[t[24]||(t[24]=e("下載了鏡像後，你按照 ",-1)),l(i,{href:"https://opensource.com/article/17/3/how-write-sd-cards-raspberry-pi"},{default:s(()=>[...t[23]||(t[23]=[e("以下的説明",-1)])]),_:1}),t[25]||(t[25]=e(" 需要解壓並安裝它到 SD 卡上。這將會花些時間安裝固件，需要些耐心。一旦安裝完成，在你的 SD 卡上將會有兩個分區。一個是用來放 bootloader ，另一個是 OpenWRT 系統。",-1))]),t[57]||(t[57]=n('<h3 id="啓動系統" tabindex="-1">啓動系統 <a class="header-anchor" href="#啓動系統" aria-label="Permalink to “啓動系統”">​</a></h3><p>要啓動你的新系統，插入 SD 卡到樹莓派，用以太網線把樹莓派和你的路由器（或者交換機）相連，然後點亮。</p><p>如果你有使用樹莓派的經驗，你可能習慣於通過終端使用 SSH 訪問過它，或者通過顯示器和鍵盤連接到樹莓派。OpenWRT 工作有一點點不同。你與這個系統交互是通過網頁瀏覽器，所以你必須能夠通過網絡來訪問你的樹莓派。</p><p>缺省狀態下，樹莓派使用的 IP 地址是：192.168.1.1。用來配置樹莓派的計算機必須和樹莓派在同一個子網中。如果你的網絡沒有使用 192.168.1.x 地址，或者你不能確定，在 GNOME 打開 “<ruby>設置<rt>Settings</rt></ruby>” ，導航到網絡設置，選擇 “<ruby>手動<rt>Manual</rt></ruby>” ，然後鍵入以下的 IP 地址和子網掩碼：</p><ul><li>IP 地址：192.168.1.15</li><li>網絡掩碼：255.255.255.0</li></ul><p><img src="https://opensource.com/sites/default/files/uploads/ipaddresses.png" alt="IP addresses" title="IP addresses"></p><p>在你的電腦上打開瀏覽器然後導航到 192.168.1.1 。這將打開一個驗證網頁，你可以登錄到你的樹莓派。</p><p><img src="https://opensource.com/sites/default/files/uploads/openwrt-login.png" alt="OpenWRT login page" title="OpenWRT login page"></p><p>首次登錄不需要密碼，所以直接點擊 “<ruby>登錄<rt>Login</rt></ruby>” 按鈕繼續。</p><h3 id="設置網絡連接" tabindex="-1">設置網絡連接 <a class="header-anchor" href="#設置網絡連接" aria-label="Permalink to “設置網絡連接”">​</a></h3><p>樹莓派只有一個以太網口，而普通路由器有兩個：一個是 WAN（有線區域網絡）口，另一個是 LAN （本地區域網絡）。</p><p>你有兩個選擇：</p><ol><li>使用你的以太網口接入互聯網</li><li>使用 WIFI 接入互聯網</li></ol><h4 id="使用以太網連接" tabindex="-1">使用以太網連接 <a class="header-anchor" href="#使用以太網連接" aria-label="Permalink to “使用以太網連接”">​</a></h4><p>你決定使用以太網，導航到 “<ruby>網絡<rt>Network</rt></ruby> → <ruby>接口<rt>Interfaces</rt></ruby>”。在這個設置頁面，按下與 “LAN” 接口對應的藍色 “<ruby>編輯<rt>Edit</rt></ruby>” 按鈕。</p><p><img src="https://opensource.com/sites/default/files/uploads/lan-interface.png" alt="LAN interface" title="LAN interface"></p><p>應該會出現一個彈窗，在這個窗口中，你需要鍵入與你將要連接樹莓派的路由器子網匹配的 IP 地址。如果需要的話，修改子網掩碼，並輸入樹莓派將要連接的路由器的 IP 地址。</p><p><img src="https://opensource.com/sites/default/files/uploads/lan-interface-ip.png" alt="Enter IP in the LAN interface" title="Enter IP in the LAN interface"></p><p>保存設置，然後通過以太網將你的樹莓派連接到路由器。你現在可以用這個新的 IP 地址訪問樹莓派。</p><p>當你在把樹莓派投入生產環境使用之前，確保為你的 OpenWRT 設置一個密碼！</p><h4 id="使用-wifi-連接" tabindex="-1">使用 WiFi 連接 <a class="header-anchor" href="#使用-wifi-連接" aria-label="Permalink to “使用 WiFi 連接”">​</a></h4><p>如果你想通過 WiFi 將樹莓派連接到互聯網，導航到 “<ruby>網絡<rt>Network</rt></ruby> → <ruby>無線<rt>Wireless</rt></ruby>” 。在 “<ruby>無線<rt>Wireless</rt></ruby>” 菜單裏，按下藍色的 “<ruby>掃描<rt>Scan</rt></ruby>” 按鈕查找你的家庭網絡。</p><p><img src="https://opensource.com/sites/default/files/uploads/scannetwork.png" alt="Scan the network" title="Scan the network"></p><p>在彈出的窗口中，找到你的 WiFi 網絡然後連接它。不要忘記 “<ruby>保存並應用<rt>Save and Apply</rt></ruby>” 設置。</p><p>在這 “<ruby>網絡<rt>Network</rt></ruby> → <ruby>接口<rt>Interfaces</rt></ruby>” 部分，你應該看到了一個新的接口。</p><p><img src="https://opensource.com/sites/default/files/uploads/newinterface.png" alt="New interface" title="New interface"></p><p>當你在把樹莓派投入生產環境使用之前，確保為你的 OpenWRT 設置一個密碼！</p><h3 id="安裝必要的軟件包" tabindex="-1">安裝必要的軟件包 <a class="header-anchor" href="#安裝必要的軟件包" aria-label="Permalink to “安裝必要的軟件包”">​</a></h3><p>默認狀態下，路由器並沒有安裝許多軟件包。OpenWRT 提供了一個包管理器，帶有一系列你需要安裝的。導航到 “<ruby>系統<rt>System</rt></ruby> → <ruby>軟件<rt>Software</rt></ruby>” 然後通過按下標有 “<ruby>更新列表…<rt>Update lists...</rt></ruby>” 的按鈕來更新你的包管理器。</p><p><img src="https://opensource.com/sites/default/files/uploads/updatesoftwarelist.png" alt="Updating packages" title="Updating packages"></p><p>你將會看到許多軟件包；你需要安裝以下這些：</p><ul><li><code>usb-modeswitch</code></li><li><code>kmod-mii</code></li><li><code>kmod-usb-net</code></li><li><code>kmod-usb-wdm</code></li><li><code>kmod-usb-serial</code></li><li><code>kmod-usb-serial-option</code></li><li><code>kmod-usb-serial-wwan</code>（如果沒有安裝的話）</li></ul>',32)),r("p",null,[t[27]||(t[27]=e("另外，",-1)),l(i,{href:"https://downloads.openwrt.org/releases/packages-21.02/aarch64_cortex-a53/luci/luci-proto-modemmanager_git-21.007.43644-ab7e45c_all.ipk"},{default:s(()=>[...t[26]||(t[26]=[e("下載這個調製解調器管理軟件包",-1)])]),_:1}),t[28]||(t[28]=e("，然後在彈出的窗口中按下標有 “",-1)),t[29]||(t[29]=r("ruby",null,[e("上傳軟件包…"),r("rt",null,"Upload Package...")],-1)),t[30]||(t[30]=e("” 的按鈕來安裝它。重啓樹莓派讓安裝包生效。",-1))]),t[58]||(t[58]=r("h3",{id:"設置移動網絡接口",tabindex:"-1"},[e("設置移動網絡接口 "),r("a",{class:"header-anchor",href:"#設置移動網絡接口","aria-label":"Permalink to “設置移動網絡接口”"},"​")],-1)),r("p",null,[t[32]||(t[32]=e("所有這些軟件包被安裝完之後，你可以設置移動網絡接口。在連接調製解調器到樹莓派之前，請閲讀 ",-1)),l(i,{href:"https://wiki.teltonika-networks.com/view/TRM240_SIM_Card"},{default:s(()=>[...t[31]||(t[31]=[e("調製解調器的説明書",-1)])]),_:1}),t[33]||(t[33]=e("，對其進行設置。然後連接你的移動調製解調器到樹莓派，然後等待一會直到調製解調器啓動。",-1))]),t[59]||(t[59]=n('<p>導航到 “<ruby>網絡<rt>Network</rt></ruby> → <ruby>接口<rt>Interfaces</rt></ruby>”。在頁面底部，按下 “<ruby>添加一個新接口…<rt>Add new interface...</rt></ruby>” 按鈕。在彈出的窗口中，給你的接口起一個名字（比如 “mobile”），然後從下拉列表中選擇 “ModemManager” 。</p><p><img src="https://opensource.com/sites/default/files/uploads/addnewinterface.png" alt="Add a new mobile interface" title="Add a new mobile interface"></p><p>按下一個標有 “<ruby>創建接口<rt>Create Interface</rt></ruby>” 的按鈕。你應該看到一個新的彈出窗口。這是設置接口的一個主窗口。在這個窗口中，選擇你的調製解調器，然後鍵入像<ruby>接入點名稱<rt>Access Point Name</rt></ruby>（APN）或是 PIN 碼之類的信息。</p><p><img src="https://opensource.com/sites/default/files/uploads/configureinterface.png" alt="Configuring the interface" title="Configuring the interface"></p><p><strong>注意：</strong> 如果在列表中沒有調製解調器設備出現，嘗試重啓樹莓派或者安裝 <code>kmod-usb-net-qmi-wwan</code> 軟件包 。</p><p>當你已經配置完你的接口，按下 “<ruby>保存<rt>Save</rt></ruby>” 然後 “<ruby>保存並應用<rt>Save and Apply</rt></ruby>”。給系統一些生效的時間。如果一切正常，你應該看到像這樣的一些東西。</p><p><img src="https://opensource.com/sites/default/files/uploads/configuredinterface.png" alt="Configured interface" title="Configured interface"></p><p>如果你想通過接口查看你的網絡連接，你可以使用 SSH 連接到你的樹莓派 shell。在終端裏，鍵入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ssh root@192.168.1.1</span></span></code></pre></div><p>缺省 IP 地址是 192.168.1.1：如果你修改了它，就用修改後的 IP 地址連接。當連接後，在終端裏執行命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ping -I ppp0 google.com</span></span></code></pre></div><p>如果一切正常運行，那麼你應該從 Google 的服務器接收到 ping 回包 。</p><p><img src="https://opensource.com/sites/default/files/uploads/terminal.png" alt="Terminal interface" title="Terminal interface"></p><p><code>ppp0</code> 是你創建的移動網絡接口的默認接口名稱。你可以通過使用 <code>ifconfig</code> 命令檢查你的接口。它只顯示活動的接口。</p><h3 id="設置防火牆" tabindex="-1">設置防火牆 <a class="header-anchor" href="#設置防火牆" aria-label="Permalink to “設置防火牆”">​</a></h3><p>要讓移動網接口運行，你需要為移動網絡接口和本地網絡接口配置防火牆，以便引導流量到正確的接口。</p><p>導航到 “<ruby>網絡<rt>Network</rt></ruby> → <ruby>防火牆<rt>Firewall</rt></ruby>”。在頁面的底部，你應該看到一個叫做 “<ruby>區域<rt>Zones</rt></ruby>” 的部分。</p><p><img src="https://opensource.com/sites/default/files/uploads/firewallzones.png" alt="Firewall zones" title="Firewall zones"></p><p>設置防火牆最簡單的方法就是調整 “wan” 區域。在 “<ruby>已覆蓋的網絡<rt>Covered networks</rt></ruby>” 選項裏按下 “<ruby>編輯<rt>Edit</rt></ruby>” 按鈕，選擇你的移動網絡接口，然後 “<ruby>保存並應用<rt>Save and Apply</rt></ruby>” 你的設置。如果你不想用 WiFi 連接你的樹莓派，你可以從 “<ruby>已覆蓋的網絡<rt>Covered networks</rt></ruby>” 裏刪除 “wwan” 接口，或者關閉 WiFi 連接。</p><p><img src="https://opensource.com/sites/default/files/uploads/firewallzonesettings.png" alt="Firewall zone settings" title="Firewall zone settings"></p><p>如果你想為每個接口設置一個獨立區域，只需創建一個新區域然後分配必要的接口即可。舉個例子，你可能想有一個覆蓋移動網絡接口的區域，並且通過它來轉發 LAN 接口流量。按下 “<ruby>添加<rt>Name</rt></ruby>” 按鈕，然後給你的區域 “<ruby>命名<rt>Name</rt></ruby>”， 檢查 “偽裝” 複選框，選中 “<ruby>已覆蓋的網絡<rt>Covered networks</rt></ruby>” ，並選擇哪些區域可以轉發其流量。</p><p><img src="https://opensource.com/sites/default/files/uploads/firewallzonepriv.png" alt="Firewall zone settings" title="Firewall zone settings"></p><p>然後 “<ruby>保存並應用<rt>Save and Apply</rt></ruby>” 這些修改。現在你有一個新的區域。</p><h3 id="設置一個接入點" tabindex="-1">設置一個接入點 <a class="header-anchor" href="#設置一個接入點" aria-label="Permalink to “設置一個接入點”">​</a></h3><p>最後一步是為你的設備接入互聯網設置一個網絡接入點。要設置一個接入點，導航到 “<ruby>網絡<rt>Network</rt></ruby> → <ruby>無線<rt>Wireless</rt></ruby>” 。你將會看到一個 WiFi 設備接口，一個名為 OpenWRT 的禁用的接入點，以及一個用於通過 WiFi 連接互聯網的連接（如果你之前沒有禁用或刪除它）。在這個禁用的接口上，按下 “<ruby>編輯<rt>Edit</rt></ruby>” 按鈕，然後 “<ruby>啓用<rt>Enable</rt></ruby>” 該接口。</p><p><img src="https://opensource.com/sites/default/files/uploads/enablewirelessnetwork.png" alt="Enabling wireless network" title="Enabling wireless network"></p><p>如果你想，你可以通過編輯 “ESSID” 選項來修改接口名稱。你也可以選擇它要關聯的網絡。默認情況下，它會與 LAN 接口關聯。</p><p><img src="https://opensource.com/sites/default/files/uploads/interfaceconfig.png" alt="Configuring the interface" title="Configuring the interface"></p><p>要為這個接口添加密碼，選擇 “<ruby>無線安全<rt>Wireless Security</rt></ruby>” 選項，選擇 “WPA2-PSK” 加密方式然後在 “<ruby>密鑰<rt>Key</rt></ruby>” 選項字段鍵入接口的密碼。</p><p><img src="https://opensource.com/sites/default/files/uploads/interfacepassword.png" alt="Setting a password" title="Setting a password"></p><p>然後 “<ruby>保存並應用<rt>Save and Apply</rt></ruby>” 設置。如果設置正確的話，當用你的設備掃描可用接入點的話，你應該可以看到你分配了名稱的新接入點。</p><h3 id="額外的軟件包" tabindex="-1">額外的軟件包 <a class="header-anchor" href="#額外的軟件包" aria-label="Permalink to “額外的軟件包”">​</a></h3><p>如果你願意，你可以通過網頁界面為你的路由器下載額外的軟件包。只需到 “<ruby>系統<rt>System</rt></ruby> → <ruby>軟件<rt>Software</rt></ruby>” 然後安裝你想從列表或者互聯網上下載的軟件包並上傳它。如果你在列表中沒有看到任何軟件包，請按下 “<ruby>更新列表…<rt>Update lists...</rt></ruby>” 按鈕。</p><p>你也可以添加其他擁有適合與 OpenWRT 一起使用的軟件包的倉庫。軟件包和它們的網頁界面是分開安裝的。軟件包名稱是以 “luci-” 開始的是網頁界面軟件包。</p><p><img src="https://opensource.com/sites/default/files/uploads/luci-packages.png" alt="Packages with luci- prefix" title="Packages with luci- prefix"></p><h3 id="試試看" tabindex="-1">試試看 <a class="header-anchor" href="#試試看" aria-label="Permalink to “試試看”">​</a></h3><p>這就是我的樹莓派路由設置的過程。</p><p><img src="https://opensource.com/sites/default/files/uploads/raspberrypirouter.jpg" alt="Raspberry Pi router" title="Raspberry Pi router"></p><p>從樹莓派建立一個路由器不是很困難。缺點是樹莓派只有一個以太網接口。你可以用一個 USB-to-Ethernet 適配器來增加更多的網口。不要忘記在接口的網站上設置網口。</p><p>OpenWRT 支持大量的移動調製解調器，你可以用管理調製解調器的通用工具 modemmanager 為它們設置移動網絡接口。</p><p>你有沒有把你的樹莓派當作路由器使用？請在評論中告訴我們情況。</p><hr>',42)),r("p",null,[t[35]||(t[35]=e("via: ",-1)),l(i,{href:"https://opensource.com/article/21/3/router-raspberry-pi"},{default:s(()=>[...t[34]||(t[34]=[e("https://opensource.com/article/21/3/router-raspberry-pi",-1)])]),_:1})]),r("p",null,[t[40]||(t[40]=e("作者：",-1)),l(i,{href:"https://opensource.com/users/lukasjan"},{default:s(()=>[...t[36]||(t[36]=[e("Lukas Janėnas",-1)])]),_:1}),t[41]||(t[41]=e(" 選題：",-1)),l(i,{href:"https://github.com/lujun9972"},{default:s(()=>[...t[37]||(t[37]=[e("lujun9972",-1)])]),_:1}),t[42]||(t[42]=e(" 譯者：",-1)),l(i,{href:"https://github.com/hwlilfe"},{default:s(()=>[...t[38]||(t[38]=[e("hwlife",-1)])]),_:1}),t[43]||(t[43]=e(" 校對：",-1)),l(i,{href:"https://github.com/wxy"},{default:s(()=>[...t[39]||(t[39]=[e("wxy",-1)])]),_:1})]),r("p",null,[t[46]||(t[46]=e("本文由 ",-1)),l(i,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[44]||(t[44]=[e("LCTT",-1)])]),_:1}),t[47]||(t[47]=e(" 原創編譯，",-1)),l(i,{href:"https://linux.cn/"},{default:s(()=>[...t[45]||(t[45]=[e("Linux中國",-1)])]),_:1}),t[48]||(t[48]=e(" 榮譽推出",-1))])])}const P=p(d,[["render",b]]);export{h as __pageData,P as default};
